from contextlib import asynccontextmanager
from pathlib import Path
import io, json, re, sqlite3, uuid
from fastapi import FastAPI, File, HTTPException, UploadFile
from fastapi.responses import HTMLResponse
from pydantic import BaseModel
from scoring import analyze

ROOT = Path(__file__).parent
(ROOT / 'data').mkdir(exist_ok=True)
(ROOT / 'uploads').mkdir(exist_ok=True)
DB = ROOT / 'data' / 'screening.db'
JOB = {'title':'Frontend Developer','description':'Build accessible web experiences with a modern frontend stack.','required_skills':['React','JavaScript','HTML','CSS'],'preferred_skills':['TypeScript','Testing','Git'],'experience_requirement':'2+ years'}
DEMO = [
 {'name':'Aarav Mehta','email':'aarav.mehta@example.com','role':'Frontend Developer','experience_years':3,'education':'B.Tech Computer Science','skills':['React','JavaScript','HTML','CSS','TypeScript','Git'],'projects':['E-commerce dashboard','Design system'],'certifications':['Meta Front-End Certificate'],'experience_summary':'3 years building production React interfaces.','summary':'Frontend engineer focused on accessible component-driven products.'},
 {'name':'Maya Shah','email':'maya.shah@example.com','role':'UI Engineer','experience_years':2,'education':'B.Sc Information Technology','skills':['React','JavaScript','HTML','CSS','Git'],'projects':['Travel planner'],'certifications':[],'experience_summary':'2 years working on responsive web applications.','summary':'UI engineer with strong core web fundamentals.'},
 {'name':'Rohan Kapoor','email':'rohan.kapoor@example.com','role':'Software Developer','experience_years':1,'education':'B.Tech Information Technology','skills':['JavaScript','HTML','CSS','Node.js'],'projects':['College event portal'],'certifications':['JavaScript Algorithms'],'experience_summary':'1 year of internship experience.','summary':'Early-career developer with a practical project portfolio.'},
 {'name':'Ishita Rao','email':'ishita.rao@example.com','role':'Frontend Developer','experience_years':4,'education':'MCA','skills':['React','JavaScript','HTML','CSS','TypeScript','Testing','Git'],'projects':['Analytics platform','Component library','Portfolio builder'],'certifications':['AWS Cloud Practitioner'],'experience_summary':'4 years delivering tested React products.','summary':'Senior frontend developer with strong testing practice.'},
 {'name':'Kabir Singh','email':'kabir.singh@example.com','role':'Web Developer','experience_years':2,'education':'Diploma in Web Design','skills':['HTML','CSS','JavaScript'],'projects':['Marketing website','Blog theme'],'certifications':[],'experience_summary':'2 years creating websites from visual designs.','summary':'Web developer with solid HTML, CSS and JavaScript foundations.'}]
class Job(BaseModel):
    title: str; description: str; required_skills: list[str]; preferred_skills: list[str]; experience_requirement: str

def connection():
    c=sqlite3.connect(DB); c.row_factory=sqlite3.Row; return c

def get_candidates():
    c=connection(); rows=[json.loads(r['data']) for r in c.execute('SELECT data FROM candidates')]; c.close(); return sorted(rows,key=lambda x:x['score'],reverse=True)

def init_db():
    c=connection(); c.execute('CREATE TABLE IF NOT EXISTS candidates (id TEXT PRIMARY KEY, data TEXT NOT NULL)')
    if c.execute('SELECT COUNT(*) FROM candidates').fetchone()[0] == 0:
        for profile in DEMO:
            profile['id']=str(uuid.uuid4()); c.execute('INSERT INTO candidates VALUES (?,?)',(profile['id'],json.dumps(analyze(profile,JOB))))
    c.commit(); c.close()

@asynccontextmanager
async def lifespan(app): init_db(); yield
app=FastAPI(title='AI Resume Screening System',lifespan=lifespan)
@app.get('/',response_class=HTMLResponse)
def home(): return HTML
@app.get('/api/health')
def health(): return {'status':'ok'}
@app.get('/api/job')
def job(): return JOB
@app.post('/api/job')
def save_job(value: Job):
    global JOB; JOB=value.model_dump(); return JOB
@app.get('/api/candidates')
def candidates(): return get_candidates()
@app.delete('/api/candidates/{candidate_id}')
def delete(candidate_id: str):
    c=connection(); c.execute('DELETE FROM candidates WHERE id=?',(candidate_id,)); c.commit(); c.close(); return {'deleted':candidate_id}

def extract(filename, content):
    if filename.lower().endswith('.pdf'):
        from pypdf import PdfReader
        return '\n'.join(page.extract_text() or '' for page in PdfReader(io.BytesIO(content)).pages)
    if filename.lower().endswith('.docx'):
        from docx import Document
        return '\n'.join(p.text for p in Document(io.BytesIO(content)).paragraphs)
    raise HTTPException(400,'Only PDF and DOCX files are supported')

def profile(text, filename):
    email=re.search(r'[\w.+-]+@[\w-]+\.[\w.-]+',text); lines=[x.strip() for x in text.splitlines() if x.strip()]
    name=lines[0] if lines else Path(filename).stem.replace('_',' ').title()
    skills=[s for s in JOB['required_skills']+JOB['preferred_skills'] if s.lower() in text.lower()]
    return {'id':str(uuid.uuid4()),'name':name,'email':email.group(0) if email else 'Not extracted','role':JOB['title'],'experience_years':2,'education':'Extracted from uploaded resume','skills':skills,'projects':['Uploaded resume project evidence'],'certifications':[],'experience_summary':'Resume text was parsed locally for relevant evidence.','summary':text[:240]}
@app.post('/api/upload')
async def upload(files: list[UploadFile]=File(...)):
    output=[]
    for f in files:
        content=await f.read(); (ROOT/'uploads'/Path(f.filename).name).write_bytes(content); result=analyze(profile(extract(f.filename,content),f.filename),JOB)
        c=connection(); c.execute('INSERT INTO candidates VALUES (?,?)',(result['id'],json.dumps(result))); c.commit(); c.close(); output.append(result)
    return output

